(() => {
 const items=window.v2Exhibits,view=new URLSearchParams(location.search).get('view')||'home';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const asset=p=>p.startsWith('v2:')?p.slice(3):''+p;
 document.querySelectorAll('.duet-pack img').forEach(img=>{const fit=()=>img.classList.toggle('wide-photo',img.naturalWidth>img.naturalHeight*1.1);if(img.complete)fit();else img.addEventListener('load',fit,{once:true});});
 document.addEventListener('archive-save-change',e=>{if(view!=='collection'||e.target.getAttribute('aria-pressed')!=='false')return;e.target.closest('.label-card')?.remove();const grid=document.querySelector('main .label-grid');if(grid&&!grid.querySelector('.label-card'))grid.innerHTML='<div class="empty"><p>这里还没有展品。</p><a class="button" href="?view=labels">去烟标索引看看 ↗</a></div>';});
 if(view==='labels'){
  const grid=document.querySelector('#label-index'),cards=[...grid.children],byCard=new Map(cards.map(card=>[card,items.find(d=>d.id===new URL(card.querySelector('.label-image').href).searchParams.get('item'))]));
  const filters=document.createElement('div');filters.className='secondary-filters';filters.innerHTML=`<label>搜索档案 <input id="exhibit-search" type="search" placeholder="名称、品牌、地域或条码" aria-label="搜索档案"></label><label>地域 <select id="exhibit-region"><option value="">全部地域</option>${[...new Set(items.map(d=>d.region))].map(r=>`<option>${esc(r)}</option>`).join('')}</select></label><label>品牌 <select id="exhibit-brand"><option value="">全部品牌</option>${[...new Set(items.map(d=>d.brand))].map(r=>`<option>${esc(r)}</option>`).join('')}</select></label><label>排列 <select id="exhibit-sort"><option value="archive">档案顺序</option><option value="name">名称</option><option value="region">地域</option></select></label><button class="text-button" id="filter-reset">清空筛选</button>`;document.querySelector('.filter-bar').after(filters);
  const pager=document.createElement('div');pager.className='gallery-pagination';pager.innerHTML='<button id="page-prev" class="button">← 上一页</button><span id="page-status" role="status"></span><button id="page-next" class="button">下一页 →</button>';grid.after(pager);
  const empty=document.createElement('div');empty.id='filter-empty';empty.className='empty';empty.textContent='没有匹配的档案。可以清空筛选，再换个关键词。';empty.hidden=true;grid.after(empty);
  let page=1;const size=24;
  function render(reset=false){if(reset)page=1;const query=document.querySelector('#exhibit-search').value.trim().toLowerCase(),region=document.querySelector('#exhibit-region').value,brand=document.querySelector('#exhibit-brand').value,theme=document.querySelector('#theme-filter').value,sort=document.querySelector('#exhibit-sort').value;
   const matching=cards.filter(card=>{const d=byCard.get(card);return (!query||(d.name+d.brand+d.region+d.title+(d.sourceSpecs?.barcode||'')+d.observations.join('')).toLowerCase().includes(query))&&(!region||d.region===region)&&(!brand||d.brand===brand)&&(!theme||d.theme===theme);});if(sort!=='archive')matching.sort((a,b)=>byCard.get(a)[sort].localeCompare(byCard.get(b)[sort],'zh-CN'));
   const pages=Math.max(1,Math.ceil(matching.length/size));page=Math.min(page,pages);const visible=new Set(matching.slice((page-1)*size,page*size));cards.forEach(card=>{card.hidden=!visible.has(card);});matching.forEach(card=>grid.append(card));document.querySelector('#filter-count').textContent=matching.length+' 件档案';document.querySelector('#page-status').textContent=matching.length?'第 '+page+' / '+pages+' 页 · 共 '+matching.length+' 件':'';document.querySelector('#page-prev').disabled=page===1;document.querySelector('#page-next').disabled=page===pages;empty.hidden=matching.length!==0;pager.hidden=matching.length===0;
  }
  filters.addEventListener('input',()=>render(true));filters.addEventListener('change',()=>render(true));document.querySelector('#theme-filter').addEventListener('change',()=>render(true));document.querySelector('#filter-reset').onclick=()=>{filters.querySelectorAll('input,select').forEach(el=>el.value=el.id==='exhibit-sort'?'archive':'');document.querySelector('#theme-filter').value='';render(true);};
  document.querySelector('#page-prev').onclick=()=>{page--;render();document.querySelector('.filter-bar').scrollIntoView({block:'start'});};document.querySelector('#page-next').onclick=()=>{page++;render();document.querySelector('.filter-bar').scrollIntoView({block:'start'});};render();
 }
 if(view==='characters'){
  const grid=document.querySelector('.character-grid'),cards=[...grid.children],controls=document.createElement('div');controls.className='character-filters';controls.innerHTML='<label>寻找角色 <input type="search" id="character-search" placeholder="输入作品名或地域"></label><span id="character-count" role="status"></span>';grid.before(controls);const more=document.createElement('button');more.className='button character-more';more.textContent='继续展开角色 ↓';grid.after(more);let limit=18;
  const filter=()=>{const q=document.querySelector('#character-search').value.trim(),matches=cards.filter((c,i)=>!q||(items[i].name+items[i].region+items[i].title).includes(q));cards.forEach(c=>c.hidden=true);matches.slice(0,limit).forEach(c=>c.hidden=false);document.querySelector('#character-count').textContent=matches.length+' 位原创形象';more.hidden=limit>=matches.length;};controls.addEventListener('input',()=>{limit=18;filter();});more.onclick=()=>{limit+=18;filter();};filter();
 }
 document.addEventListener('click',e=>{
  const image=e.target.closest('[data-image]');if(image){const dialog=document.querySelector('#image-view');let link=document.querySelector('#image-native');if(!link){link=document.createElement('a');link.id='image-native';link.target='_blank';link.rel='noopener';link.textContent='原尺寸 ↗';dialog.querySelector('.image-toolbar').append(link);}const selected=items.find(d=>new URL(asset(d.portrait),location.href).href===new URL(image.dataset.image,location.href).href);link.href=selected?asset(selected.nativeArt):image.dataset.image;dialog.querySelector(':scope>p').textContent=selected?'非官方原创角色 · 可放大并滑动查看 · 原尺寸保留完整画面':'原始包装参考图 · 放大不代表高清或许可已确认';}
 });
 if(view==='votes')document.querySelector('main').innerHTML=`<section class="page-heading"><p class="eyebrow">DESIGN & MEMORY <span>图案如何被记住</span></p><h1>留下印象的，<em>是哪一道线？</em></h1><p>从建筑、草木和纸面秩序出发，记录观看中的偏爱。这里关注设计与文化记忆，不评价口感、购买价值或销量。</p></section><section class="memory-rooms">${[['建筑的回声','横向屋檐、层楼与竖起的塔影。','sku-yanpk-213'],['印刷的秩序','从边框走到留白，跟着视线移动。','sku-yanpk-5611'],['草木的另一面','花瓣、叶形和枝脉，怎样进入角色。','sku-yanpk-851']].map(([title,copy,id])=>{const d=items.find(d=>d.id===id);return `<a class="memory-room" href="?view=detail&item=${id}"><img src="${asset(d.preview)}" alt="${esc(d.title)}"><span>DESIGN STUDY</span><h2>${title}</h2><p>${copy}</p><b>从一件作品开始 ↗</b></a>`;}).join('')}</section><section class="memory-note"><h2>把偏爱留在本地收藏。</h2><p>可以在展品卡片上点爱心，保存你记住的设计。公众投票尚未开放，此页没有票数或排名。</p><a class="button" href="?view=collection">查看我的收藏 ↗</a></section>`;
})();
